create table if not exists public.live_network_events (id uuid primary key default gen_random_uuid(), event_type text not null, location_id uuid null, actor_type text not null default 'user', actor_id uuid null, payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()); create index if not exists live_network_events_created_at_idx on public.live_network_events(created_at desc); create index if not exists live_network_events_location_idx on public.live_network_events(location_id, created_at desc); create index if not exists live_network_events_type_idx on public.live_network_events(event_type, created_at desc); alter table public.live_network_events enable row level security; create policy live_network_events_select_authenticated on public.live_network_events for select to authenticated using (true); create policy live_network_events_insert_authenticated on public.live_network_events for insert to authenticated with check (actor_id = auth.uid() or actor_id is null);
